		["#Entry_28"]="ein gehängter Mann|bringt dir|heute kein Glück",
		["#Entry_29"]="der getarnte Teufel",
		["#Entry_30"]="niemand weiß,|welche Mühen|du erlebt hast",
		["#Entry_31"]="sei nicht verletzt,|andere haben|auch Probleme",
